// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llm.localimport android.content.Contextimport com.roshan.persona.brain.llm.registry.LocalLlmModelimport com.roshan.persona.brain.llm.registry.LocalLlmModelCatalogimport timber.log.Timber/** * NOUS — Local Model Manager. * * Manages the lifecycle of local LLM models: *   - Track which models are downloaded *   - Track active (loaded) model *   - Provide LlamaCppProvider instances for loaded models *   - App-Heap-aware model selection * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§5 Quantization Selector</a> */class LocalModelManager(    private val modelCatalog: LocalLlmModelCatalog,    private val context: Context,) {    /** Currently loaded provider (null = no model loaded). */    @Volatile    private var currentProvider: LlamaCppProvider? = null    /** Currently loaded model ID. */    @Volatile    private var currentModelId: String? = null    /**     * Load a model by ID. Unloads any previously loaded model first.     *     * @param modelId the model to load (must be downloaded)     * @return LlamaCppProvider if loaded successfully, null on failure     */    suspend fun loadModel(modelId: String): LlamaCppProvider? {        // Unload current model first        unloadCurrentModel()        val model = modelCatalog.getById(modelId)            ?: run {                Timber.e("Model not found: $modelId")                return null            }        if (!model.isDownloaded || model.localFilePath == null) {            Timber.e("Model not downloaded: $modelId")            return null        }        // Check if GPU should be used        val gpuAvailable = if (LlamaCppJni.ensureLoaded()) {            try { LlamaCppJni.nativeIsGpuAvailable() } catch (e: Throwable) { false }        } else false        val useGpu = VulkanConfig.shouldUseGpu(gpuAvailable)        val provider = LlamaCppProvider(            modelPath = model.localFilePath ?: return null,            modelId = model.id,            contextLength = model.contextLength,            modelSizeBytes = model.sizeBytes,            useGpu = useGpu,            useMmap = true,  // v2.1: always use mmap to prevent OOM        )        val loadResult = provider.load()        if (loadResult is com.roshan.persona.common.Result.Success) {            currentProvider = provider            currentModelId = modelId            Timber.i("Model loaded: ${model.id} (GPU=$useGpu, mmap=true)")            return provider        } else {            Timber.e("Failed to load model: $modelId — $loadResult")            return null        }    }    /**     * Unload the currently loaded model.     */    suspend fun unloadCurrentModel() {        currentProvider?.let { provider ->            provider.unload()            Timber.i("Model unloaded: $currentModelId")        }        currentProvider = null        currentModelId = null    }    /**     * Get the currently loaded provider (null if no model loaded).     */    fun getCurrentProvider(): LlamaCppProvider? = currentProvider    /**     * Get the currently loaded model ID (null if no model loaded).     */    fun getCurrentModelId(): String? = currentModelId    /**     * Whether any model is currently loaded.     */    fun isModelLoaded(): Boolean = currentProvider != null    /**     * Get the recommended model for this device (App-Heap-aware).     */    fun getRecommendedModel(): LocalLlmModel? {        return QuantizationSelector.recommendModel(context, modelCatalog)    }    /**     * Pause generation (app went to background).     * v2.1 Fix #12: Vulkan context loss prevention.     */    fun pauseGeneration() {        currentProvider?.stopGeneration()    }    /**     * Resume generation (app returned to foreground).     * Checks if Vulkan context is still valid; reloads if lost.     *     * @return true if model is ready, false if reload needed     */    suspend fun resumeGeneration(): Boolean {        val provider = currentProvider ?: return false        if (!provider.isContextValid()) {            Timber.w("Vulkan context lost — reloading model")            val modelId = currentModelId            unloadCurrentModel()            if (modelId != null) {                loadModel(modelId)                return currentProvider != null            }            return false        }        return true    }}